    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;Description&gt;Zile Lucratoare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:3031,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Preluare Zile Lucratoare&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4367,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;;WITH Zile AS (\n    SELECT DATEFROMPARTS(@Anul, @Luna, 1) AS Data\n    UNION ALL\n    SELECT DATEADD(DAY, 1, Data)\n    FROM Zile\n    WHERE MONTH(DATEADD(DAY, 1, Data)) = @Luna\n)\nSELECT COUNT(*) AS ZileLucratoare\nFROM Zile\nWHERE DATENAME(WEEKDAY, Data) NOT IN (&#39;Saturday&#39;, &#39;Sunday&#39;)\nOPTION (MAXRECURSION 40);\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;ZileLucratoare&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:3032,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Zile Lucratoare&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4367,&quot;ActionType&quot;:&quot;ApplyTokens&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[ZileLucratoare]&quot;,&quot;name&quot;:&quot;ZileLucratoareLunar&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;Description&gt;Exceptii Calcul Lichidare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:3033,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Calcul Numar Exceptii&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4370,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (\n    SELECT\n        [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare\n)\n\nSELECT COUNT(*) AS NrExceptii\nFROM (\n    SELECT a.Id\n    FROM app.Salariat a\nCROSS JOIN Parametri p\n    OUTER APPLY (\n    SELECT\n        SUM(\n            CASE\n                WHEN c.Interval1DatadeInceput IS NOT NULL\n                 AND MONTH(c.Interval1DatadeInceput) = @Luna\n                 AND YEAR (c.Interval1DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO1, 0)\n                ELSE 0\n            END\n          + CASE\n                WHEN c.Interval2DatadeInceput IS NOT NULL\n                 AND MONTH(c.Interval2DatadeInceput) = @Luna\n                 AND YEAR (c.Interval2DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO2, 0)\n                ELSE 0\n            END\n          + CASE\n                WHEN c.Interval3DatadeInceput IS NOT NULL\n                 AND MONTH(c.Interval3DatadeInceput) = @Luna\n                 AND YEAR (c.Interval3DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO3, 0)\n                ELSE 0\n            END\n        ) AS ZileCOLuna\n    FROM app.ConcediudeOdihna c\n    WHERE c.Marca        = a.Marca\n      AND c.CodSucursala = @CodSucursala\n) co\n\n    OUTER APPLY (\n        SELECT\n            SUM(m.TotZileLucratoare) AS ZileCMLuna\n        FROM app.ConcediuMedical m\n        WHERE m.Marca = a.Marca\n          AND m.CodSucursala = @CodSucursala\n          AND m.AnulDePlata = @Anul\n          AND m.LunaDePlata = @Luna\n    ) cm\n\n    WHERE\n        a.Anul = @Anul\n        AND a.Luna = @Luna\n        AND a.CodSucursala = @CodSucursala\n        AND (\n            p.ZileLucratoare\n            - ISNULL(co.ZileCOLuna,0)\n            - ISNULL(cm.ZileCMLuna,0)\n        ) &amp;lt;= 0\n) x;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;p_NrExceptii&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:3034,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verificare Exceptii !=0&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4370,&quot;ActionType&quot;:&quot;ShowToastAndContinue&quot;,&quot;Condition&quot;:&quot;[p_NrExceptii:NrExceptii] != 0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Atentionare Exceptii!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Există [p_NrExceptii] salariați cu excepții de lichidare (CO / CM). Verifică lista &#238;nainte de calcul.&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;plain&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;3&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:3035,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verificare Exceptii == 0&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4370,&quot;ActionType&quot;:&quot;ShowToastAndContinue&quot;,&quot;Condition&quot;:&quot;[p_NrExceptii:NrExceptii] == 0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:2,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Calcul Lichidare&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Asteptati! Se calculeaza Lichidarea!&amp;lt;/p&amp;gt;&amp;lt;p&amp;gt;Debug: NrExceptii=[p_NrExceptii]&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;success&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;3&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;bottom-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;Condition&gt;0&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;3&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;Description&gt;Verificare Status Calcul taxe Pensii Alimenatre&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:3036,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4373,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:&quot;[Helper:TokenStatusCalculTaxePostale] == 1&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:null,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Aveti Calcul Taxe Pensii Alimentare neconfirmat!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;default&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;3&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;Condition&gt;[Helper:TokenStatusCalculTaxePostale] == 1&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;4&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;Description&gt;Calcul Lichidare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;/*=====================================================\n    0️⃣ Declarare Statusuri\n=====================================================*/\nDECLARE @StatusDraft INT\nDECLARE @StatusBlocat INT\n\nSELECT @StatusDraft = Id \nFROM app.StatusCalcul \nWHERE Denumire = &#39;Draft&#39;\n\nSELECT @StatusBlocat = Id \nFROM app.StatusCalcul \nWHERE Denumire = &#39;Blocat&#39;\n\n\n/*=====================================================\n    1️⃣ Creează ControlLichidare dacă nu există\n=====================================================*/\nIF NOT EXISTS (\n    SELECT 1\n    FROM app.ControlLichidare\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n)\nBEGIN\n    INSERT INTO app.ControlLichidare\n    (\n        Anul,\n        Luna,\n        CodSucursala,\n        Status,\n        CreatDe,\n        DataCreare\n    )\n    VALUES\n    (\n        @Anul,\n        @Luna,\n        @CodSucursala,\n        @StatusDraft,\n        @UserName,\n        GETDATE()\n    )\nEND\n\n\n/*=====================================================\n    2️⃣ Oprește dacă luna este Blocată\n=====================================================*/\nIF EXISTS (\n    SELECT 1\n    FROM app.ControlLichidare\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n      AND Status = @StatusBlocat\n)\nBEGIN\n    RAISERROR (&#39;Luna este blocata. Deblocati pentru recalcul.&#39;,16,1)\n    RETURN\nEND\n\n\n/*=====================================================\n    3️⃣ Ștergere calcul existent\n=====================================================*/\nDELETE FROM app.CalculLichidare\nWHERE Anul = @Anul\n  AND Luna = @Luna\n  AND CodSucursala = @CodSucursala\n\n\n/*=====================================================\n    4️⃣ Motor calcul\n=====================================================*/\n\n;WITH Parametri AS \n(\n    ( SELECT [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare )\n)\n\nINSERT INTO app.CalculLichidare\n(\n    IdSalariat,\n    CodSucursala,\n    Marca,\n    TipNorma,\n    ZileLucratoare,\n    ZileCO,\n    ZileCM,\n    ZileLucrate,\n    OreLucrate,\n    SalariuBrut,\n    SalBrutEfectiv,\n    TicheteMasa,\n    Agenti,\n    Remiza,\n    AlteDrepturi,\n    BrutContributiv,\n    TotalBrut,\n    CAS,\n    CASS,\n    CAM,\n    BazaImpozabila,\n    ImpozitVenit,\n    CAR,\n    PensiiAlimentare,\n    PensiiFacultative,\n    AlteRetineri,\n    VenitNet,\n    SalariuNet,\n    NetDePlata,\n    Anul,\n    Luna,\n    DataCalcul,\n    Status\n)\n\nSELECT\n    a.Id,\n    @CodSucursala,\n    a.Marca,\n    a.TipNorma,\n\n    p.ZileLucratoare,\n    ISNULL(co.ZileCOLuna,0),\n    ISNULL(cm.ZileCMLuna,0),\n    zl.ZileLucrate,\n\n    ca.OreLucrate,\n    b.Salariu,\n    ca.SalBrutEfectiv,\n    ca.TicheteTotale,\n    ISNULL(ag.SumaAgent,0),\n    ISNULL(rem.Sume_Remiza,0),\n    0,\n    ca.BrutContributiv,\n    ca.TotalBrut,\n    ca.CAS,\n    ca.CASS,\n    0,\n    ca.BazaImpozabila,\n    ca.ImpozitVenit,\n    0, --CAR\n    ISNULL(pa.PensiiAlimentare,0),\n    0, --Pensie Facultativa\n    0,\n    ca.VenitNet,\n    ca.SalariuNet,\n    CASE \n   WHEN ca.SalariuNet - ISNULL(pa.PensiiAlimentare,0) &amp;lt; 0\n   THEN 0\n   ELSE ca.SalariuNet - ISNULL(pa.PensiiAlimentare,0)\nEND ,\n  \n    @Anul,\n    @Luna,\n    GETDATE(),\n    @StatusDraft\n\nFROM app.Salariat a\nLEFT JOIN app.NomGrilaSalarizare b\n       ON b.Clasa = a.Clasa\n      AND b.TipMediu = &#39;U&#39;\n\nLEFT JOIN app.TSTichetMasa t\n       ON t.Anul = @Anul\n      AND t.Luna = @Luna\n\nCROSS JOIN Parametri p\n\nOUTER APPLY (\n    SELECT\n        SUM(\n              CASE WHEN MONTH(c.Interval1DatadeInceput)=@Luna\n               AND YEAR(c.Interval1DatadeInceput)=@Anul\n              THEN ISNULL(c.NrZileCO1,0) ELSE 0 END\n            + CASE WHEN MONTH(c.Interval2DatadeInceput)=@Luna\n               AND YEAR(c.Interval2DatadeInceput)=@Anul\n              THEN ISNULL(c.NrZileCO2,0) ELSE 0 END\n            + CASE WHEN MONTH(c.Interval3DatadeInceput)=@Luna\n               AND YEAR(c.Interval3DatadeInceput)=@Anul\n              THEN ISNULL(c.NrZileCO3,0) ELSE 0 END\n        ) AS ZileCOLuna\n    FROM app.ConcediudeOdihna c\n    WHERE c.Marca = a.Marca\n      AND c.CodSucursala = @CodSucursala\n) co\n\nOUTER APPLY (\n    SELECT SUM(m.TotZileLucratoare) AS ZileCMLuna\n    FROM app.ConcediuMedical m\n    WHERE m.Marca = a.Marca\n      AND m.CodSucursala = @CodSucursala\n      AND m.AnulDePlata = @Anul\n      AND m.LunaDePlata = @Luna\n) cm\n\nCROSS APPLY (\n    SELECT\n        CASE\n            WHEN p.ZileLucratoare\n                 - ISNULL(co.ZileCOLuna,0)\n                 - ISNULL(cm.ZileCMLuna,0) &amp;lt; 0\n            THEN 0\n            ELSE p.ZileLucratoare\n                 - ISNULL(co.ZileCOLuna,0)\n                 - ISNULL(cm.ZileCMLuna,0)\n        END AS ZileLucrate\n) zl\n\nOUTER APPLY (\n    SELECT SUM(ISNULL(ca2.Suma,0)) AS SumaAgent\n    FROM app.CalculAgent ca2\n    WHERE ca2.Marca = a.Marca\n      AND ca2.Anul = @Anul\n      AND ca2.Luna = @Luna\n      AND ca2.CodSucursala = @CodSucursala\n) ag\n\nOUTER APPLY (\n    SELECT SUM(ISNULL(x.Suma,0)) AS Sume_Remiza\n    FROM app.Remiza x\n    WHERE x.Marca = a.Marca\n      AND x.Anul = @Anul\n      AND x.Luna = @Luna\n      AND x.CodSucursala = @CodSucursala\n) rem\nOUTER APPLY (\n    SELECT \n        SUM(\n              ISNULL(p.Rata,0)\n            + ISNULL(p.Rest,0)\n            + ISNULL(p.Taxa,0)\n            + ISNULL(p.Taxam,0)\n        ) AS PensiiAlimentare\n    FROM app.PensieAlimentara p\n    WHERE p.Marca = a.Marca\n      AND p.Anul = @Anul\n      AND p.Luna = @Luna\n      AND p.CodSucursala = @CodSucursala\n) pa\n\nCROSS APPLY (\n    SELECT\n        zl.ZileLucrate * a.TipNorma * 8 AS OreLucrate,\n        ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0) AS SalBrutEfectiv,\n        ISNULL(t.Valoare,0) * zl.ZileLucrate AS TicheteTotale,\n        (\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n        ) AS BrutContributiv,\n        (\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n            + (ISNULL(t.Valoare,0) * zl.ZileLucrate)\n        ) AS TotalBrut,\n        ROUND((\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n        ) * 0.25,0) AS CAS,\n        ROUND((\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n            + (ISNULL(t.Valoare,0) * zl.ZileLucrate)\n        ) * 0.10,0) AS CASS,\n        (\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) AS BazaImpozabila,\n        ROUND((\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) * 0.10,0) AS ImpozitVenit,\n        (\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) * 0.90 AS SalariuNet,\n        (\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) * 0.90 AS VenitNet\n) ca\n\nWHERE \na.CodSucursala = @CodSucursala\nAND a.Anul = @Anul\nAND a.Luna = @Luna\n\n\n/*=====================================================\n    5️⃣ Validare: dacă nu s-a inserat nimic → eroare\n=====================================================*/\nIF NOT EXISTS (\n    SELECT 1\n    FROM app.CalculLichidare\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n)\nBEGIN\n    RAISERROR (&#39;Nu s-au generat inregistrari pentru aceasta luna.&#39;,16,1)\n    RETURN\nEND\n\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:UserName]&quot;,&quot;name&quot;:&quot;Username&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true}&lt;/ActionData&gt;
      &lt;Condition&gt;0&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;5&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RedirectToPage&lt;/ActionType&gt;
      &lt;Description&gt;Redirectare catre Calcul Lichidare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;PageId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;191&quot;},&quot;EnforceCurrentLocale&quot;:false,&quot;QueryString&quot;:null,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false}&lt;/ActionData&gt;
      &lt;Condition /&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;TransferBancarPlatiSalariale&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RedirectToPage&lt;/ActionType&gt;
      &lt;ActionData&gt;{&quot;PageId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;281&quot;},&quot;EnforceCurrentLocale&quot;:false,&quot;QueryString&quot;:null,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;SalvareLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RedirectToPage&lt;/ActionType&gt;
      &lt;Description&gt;Redirectare catre Pagina Lichidare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;PageId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;163&quot;},&quot;EnforceCurrentLocale&quot;:false,&quot;QueryString&quot;:null,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;VizualizareFluturas&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RedirectToPage&lt;/ActionType&gt;
      &lt;ActionData&gt;{&quot;PageId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;355&quot;},&quot;EnforceCurrentLocale&quot;:false,&quot;QueryString&quot;:null,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false}&lt;/ActionData&gt;
