      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;Result.StopExecution&lt;/ActionType&gt;
      &lt;ActionData&gt;{}&lt;/ActionData&gt;
      &lt;Condition&gt;Luna = [GetOrSession:MonthV] &amp;amp;&amp;amp; Anul = [GetOrSession:YearV]&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
