    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileLucratoare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ApplyTokens&lt;/ActionType&gt;
      &lt;Description&gt;Token ZIle Lucratoare (Luna si An)&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[Initializari:ZileLucratoare(Anul=[GetOrSession:YearV], Luna=[GetOrSession:MonthV])]&quot;,&quot;name&quot;:&quot;ZileLucratoare&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileLucratoare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;ActionType&gt;UpdateForm&lt;/ActionType&gt;
      &lt;ActionData&gt;{}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileCOLunar&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;Result.StopExecution&lt;/ActionType&gt;
      &lt;ActionData&gt;{}&lt;/ActionData&gt;
      &lt;Condition&gt;[GetOrSession:Year] == &quot;&quot; || [GetOrSession:Month] == &quot;&quot;&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileCOLunar&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;Description&gt;Calcul Zile CO in luna sesiunii curente&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;SELECT\n    ISNULL(\n        SUM(\n            CASE WHEN MONTH(Interval1DatadeInceput) = @Luna AND YEAR(Interval1DatadeInceput) = @Anul\n                 THEN NrZileCO1 ELSE 0 END\n          + CASE WHEN MONTH(Interval2DatadeInceput) = @Luna AND YEAR(Interval2DatadeInceput) = @Anul\n                 THEN NrZileCO2 ELSE 0 END\n          + CASE WHEN MONTH(Interval3DatadeInceput) = @Luna AND YEAR(Interval3DatadeInceput) = @Anul\n                 THEN NrZileCO3 ELSE 0 END\n        ), 0\n    ) AS TotalZileCO_Luna\nFROM app.ConcediudeOdihna\nWHERE Marca = @marca;\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[GET:p_Marca]&quot;,&quot;name&quot;:&quot;marca&quot;}],&quot;OutputTokenName&quot;:&quot;row&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileCOLunar&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ApplyTokens&lt;/ActionType&gt;
      &lt;Description&gt;Creare Token pentru Zile CO pentru marca selectată + luna/an din Session.&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[row:TotalZileCO_Luna]&quot;,&quot;name&quot;:&quot;ZileCOLuna&quot;}],&quot;TokenizeTokenNames&quot;:false,&quot;RecursionCount&quot;:&quot;1&quot;}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileCOLunar&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;3&lt;/OrderIndex&gt;
      &lt;ActionType&gt;UpdateForm&lt;/ActionType&gt;
      &lt;ActionData&gt;{}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
  &lt;/Actions&gt;
&lt;/ActionForm&gt;
